const buckets = new Map();

export function allow(key, limit, windowMs, now = Date.now()) {
  const b = buckets.get(key) ?? { count: 0, start: now };
  if (now - b.start > windowMs) {
    b.count = 0;
    b.start = now;
  }
  b.count++;
  buckets.set(key, b);
  return b.count <= limit;
}
